# Within each tier: subsample dev, then split train/val
def run_tier(X_dev, y_dev, X_test, y_test, label, n_dev):
    if n_dev is not None:
        Xd, yd = _subsample(X_dev, y_dev, min(n_dev, len(y_dev)))
    else:
        Xd, yd = X_dev, y_dev

    X_train, X_val, y_train, y_val = train_test_split(
        Xd, yd, test_size=VAL_FRAC, stratify=yd, random_state=SEED,
    )
    # ... preprocess (fit scaler on train only), then run shared pipeline

@staticmethod def _encode_categoricals(X: pd.DataFrame) -> pd.DataFrame: """SEX → binary; EDUCATION and MARRIAGE → one-hot (drop_first=True).""" X = X.copy() if "SEX" in X.columns: X["SEX"] = X["SEX"].map({1: 0, 2: 1}).astype(int) # 1=male→0, 2=female→1 ohe_cols = [c for c in ["EDUCATION", "MARRIAGE"] if c in X.columns] if ohe_cols: X = pd.get_dummies(X, columns=ohe_cols, drop_first=True, dtype=int) return X
def fit_transform(self, X: pd.DataFrame) -> pd.DataFrame: """Fit encoders/scaler on X (training set) and return transformed copy.""" X_enc = self._encode_categoricals(X) num_cols = [c for c in _NUMERIC if c in X_enc.columns] self._numeric_cols = num_cols self._scaler = StandardScaler() X_enc = X_enc.copy() X_enc[num_cols] = self._scaler.fit_transform(X_enc[num_cols].astype(float)) return X_enc
def transform(self, X: pd.DataFrame) -> pd.DataFrame: """Apply the already-fitted scaler to a new split (no re-fitting).""" X_enc = self._encode_categoricals(X) X_enc = X_enc.reindex(columns=self._encoded_cols, fill_value=0) # align dummies X_enc = X_enc.copy() X_enc[self._numeric_cols] = self._scaler.transform( X_enc[self._numeric_cols].astype(float) ) return X_enc

def fit_probability_calibrator(
    method: str,
    y_prob: np.ndarray,
    y_true: np.ndarray,
) -> FittedCalibrator:
    """Fit a post-hoc calibrator from predicted probabilities."""
    probs = np.clip(np.asarray(y_prob, dtype=float), 1e-6, 1.0 - 1e-6)
    targets = np.asarray(y_true, dtype=int)
    if method == "platt":
        logits = np.log(probs / (1.0 - probs)).reshape(-1, 1)
        model = LogisticRegression(solver="lbfgs", random_state=42)
        model.fit(logits, targets)
        return FittedCalibrator(method=method, model=model)
    if method == "isotonic":
        model = IsotonicRegression(out_of_bounds="clip")
        model.fit(probs, targets)
        return FittedCalibrator(method=method, model=model)

def find_optimal_threshold(y_true, y_prob, metric="f1", lo=0.01, hi=0.99,
                           step=0.001):
    thresholds = np.arange(lo, hi + step, step)
    best_t, best_v = 0.5, 0.0
    for t in thresholds:
        y_pred = (y_prob >= t).astype(int)
        if metric == "f1":
            v = f1_score(y_true, y_pred, zero_division=0.0)
        if v > best_v:
            best_v, best_t = v, t
    return best_t, best_v
